    if(root.matches('a[href^="https://wa.me/"]')) renderValue(root,'href',()=>root.getAttribute('href'),v=>root.setAttribute('href',v),value=>{
      const url=new URL(value);const message=url.searchParams.get('text'); if(message)url.searchParams.set('text',translateMessage(message));return url.toString();
    });
